Input: {"question": "What is the profession of Nigel Harris?", "source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0440-2a521b20aa23:d00", "start": 0, "end": 67, "text": "Nigel Harris (actor) Nigel Harris (\"born\" 1949) is a British actor."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0440-2a521b20aa23:d00", "start": 68, "end": 113, "text": "Harris was born in Grahamstown, South Africa."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0440-2a521b20aa23:d00", "start": 114, "end": 299, "text": "He is the son of the philosopher, Errol Harris, and grandson of Samuel Harris, who with Cecil Rhodes was one of the defenders of Kimberly when the town was besieged during the Boer War."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0440-2a521b20aa23:d00", "start": 300, "end": 318, "text": "He obtained a B.A."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0440-2a521b20aa23:d00", "start": 319, "end": 440, "text": "in Philosophy at the University of Nottingham in 1971, where he was the External Affairs Chairman of the Students’ Union."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0440-2a521b20aa23:d00", "start": 441, "end": 575, "text": "He trained as a drama teacher at Alsager College of Education (where he acted with and became close friends with Joe Leeway, who later"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0440-2a521b20aa23:d01", "start": 0, "end": 111, "text": "was one of the first people to try to analyse the global shift in production towards parts of the global south."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0440-2a521b20aa23:d01", "start": 112, "end": 207, "text": "He argued that this shift was undermining the idea of a unified and impoverished 'third world'."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0440-2a521b20aa23:d01", "start": 208, "end": 390, "text": "In political terms it had also undermined the 'national liberation' model that had dominated the anti-colonial struggles and the arguments in the immediate post independence decades."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0440-2a521b20aa23:d01", "start": 391, "end": 500, "text": "But over time he was also led to question aspects of his earlier analysis as well as that of a wider Marxism."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0440-2a521b20aa23:d01", "start": 501, "end": 591, "text": "Harris increasingly took the view that capitalism, seen as an economic system, and left to"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0440-2a521b20aa23:d02", "start": 0, "end": 157, "text": ", and Director of Postgraduate Studies ( including a course for aid-supported graduates from developing countries on urbanization in developing countries ) ."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0440-2a521b20aa23:d02", "start": 158, "end": 199, "text": "1965-1967 Lecturer , University of York ."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0440-2a521b20aa23:d02", "start": 200, "end": 281, "text": "1964-1965 Lecturer in South-East Asian Studies , IC University , Mitaka , Tokyo ."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0440-2a521b20aa23:d02", "start": 282, "end": 425, "text": "1963-1964 ( i ) Research Fellow , Indian Statistical Institute , Calcutta ( topic : Problems in the formation of an industrial labour force ) ."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0440-2a521b20aa23:d02", "start": 426, "end": 591, "text": "( ii ) International Editor , The Economic and Political Weekly , Bombay ; and correspondent for The Economist , London , Far Eastern Economic Review , Hong Kong etc"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0440-2a521b20aa23:d03", "start": 0, "end": 121, "text": "take place in St Michael's Church throughout the year with the Canterbury Cathedral choir visiting in the summer of 2006."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0440-2a521b20aa23:d03", "start": 122, "end": 245, "text": "The St Michael's Choir and organists visit other churches to sing Evensong including several visits to Rochester Cathedral."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0440-2a521b20aa23:d03", "start": 246, "end": 475, "text": "MacArthur has recently written a book, \"Ships in Troubled Waters\", () which details his life at boarding school and on several offshore radio stations, including Radio Caroline, the Voice of Peace and the offshore Radio Paradise."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0440-2a521b20aa23:d03", "start": 476, "end": 623, "text": "Nigel MacArthur Nigel MacArthur, also known as Stuart Russell and Nigel Harris, is a freelance broadcaster in Kent on Radio Caroline, EKR and KMFM."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0440-2a521b20aa23:d03", "start": 624, "end": 641, "text": "MacArthur's first"}}, "candidates": [{"candidate_id": "C0", "answer": "actor", "card_ids": ["ramdocs-0440-2a521b20aa23:d00:c0"]}, {"candidate_id": "C1", "answer": "Lecturer", "card_ids": ["ramdocs-0440-2a521b20aa23:d02:c0"]}, {"candidate_id": "C2", "answer": "freelance broadcaster", "card_ids": ["ramdocs-0440-2a521b20aa23:d03:c0"]}], "original_cards": [{"doc_id": "ramdocs-0440-2a521b20aa23:d00", "card_id": "ramdocs-0440-2a521b20aa23:d00:c0", "entity": "Nigel Harris", "scope": "profession", "claim": "Nigel Harris is an actor.", "answer": "actor", "quote": "Nigel Harris (actor) Nigel Harris (\"born\" 1949) is a British actor.", "original_document_number": 1}, {"doc_id": "ramdocs-0440-2a521b20aa23:d02", "card_id": "ramdocs-0440-2a521b20aa23:d02:c0", "entity": "Nigel Harris", "scope": "1963-1967", "claim": "Nigel Harris was a Lecturer from 1963 to 1967.", "answer": "Lecturer", "quote": ", and Director of Postgraduate Studies ( including a course for aid-supported graduates from developing countries on urbanization in developing countries ) . 1965-1967 Lecturer , University of York . 1964-1965 Lecturer in South-East Asian Studies , IC University , Mitaka , Tokyo . 1963-1964 ( 